namespace sv_b5adfe0815dd43c49b1439c74a4fbe57;

public static class TimeFormatHelper
{
    public static string ToRelative(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

.message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e0e0e0;
    background: #fff;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input textarea:focus {
    border-color: #4a76a8;
}

.message-input button {
    padding: 8px 20px;
    background: #4a76a8;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
    align-self: flex-end;
    transition: background 0.15s;
}

.message-input button:hover:not(:disabled) {
    background: #3a6090;
}

.message-input button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.message-item {
    position: relative;
    padding: 8px 16px;
    border-radius: 4px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #f5f5f5;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1a1a1a;
}

.timestamp {
    font-size: 0.75rem;
    color: #888;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.45;
    color: #333;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    background: #e8eef4;
    border: 1px solid #ccd6e0;
    border-radius: 12px;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #d0dce8;
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    padding: 2px 0;
    font-size: 0.8rem;
    color: #4a76a8;
    background: none;
    border: none;
    cursor: pointer;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1);
    padding: 2px;
}

.message-actions button {
    padding: 4px 8px;
    font-size: 0.75rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    white-space: nowrap;
}

.message-actions button:hover {
    background: #f0f0f0;
}

.emoji-picker {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    padding: 6px;
    z-index: 10;
}

.emoji-picker button {
    font-size: 1.2rem;
    padding: 4px 6px;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.1s;
}

.emoji-picker button:hover {
    background: #f0f0f0;
}

.channel-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2c2f33;
    color: #dcddde;
    overflow-y: auto;
}

.channel-list-title {
    padding: 16px 16px 8px;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
    margin: 0;
}

.channel-list ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.channel-entry {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 1px 8px;
    transition: background 0.1s;
}

.channel-entry:hover {
    background: #34373c;
}

.channel-entry.active {
    background: #404449;
    color: #fff;
}

.channel-name-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.channel-name {
    font-size: 0.9rem;
    font-weight: 500;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.channel-entry.active .channel-name {
    font-weight: 700;
}

.unread-badge {
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
    flex-shrink: 0;
}

.channel-desc {
    font-size: 0.75rem;
    color: #72767d;
    margin-top: 2px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

