arguments.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_b5adfe0815dd43c49b1439c74a4fbe57.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     SelectedChannelId="selectedChannel?.Id"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main">
        <MessageArea Channel="selectedChannel"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     IsLoadingMore="isLoadingMore"
                     HasMoreMessages="hasMoreMessages"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="AddReaction"
                     OnLoadMore="LoadMoreMessages" />
    </div>

    @if (threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];
    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = [];
        threadSummaries.Clear();
        hasMoreMessages = true;
        threadRootMessage = null;
        threadReplies = [];

        var loaded = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messages = loaded;
        hasMoreMessages = loaded.Count == PageSize;
        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channel.Id);
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || !hasMoreMessages || selectedChannel is null) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        messages.InsertRange(0, older);
        hasMoreMessages = older.Count == PageSize;
        BuildThreadSummaries();

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        var thread = await ChatService.GetThreadAsync(messageId);
        threadReplies = thread.Where(m => m.Id != messageId).ToList();
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        var rootId = threadRootMessage.Id;
        threadSummaries[rootId] = new ThreadSummary(rootId, threadReplies.Count, reply.SentAt);
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        if (selectedChannel is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
            messages = refreshed;
        }
    }

    private void BuildThreadSummaries()
    {
        var repliesByRoot = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in repliesByRoot)
        {
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
}

.chat-sidebar {
    width: 260px;
    flex-shrink: 0;
    border-right: 1px solid #23272a;
}

.chat-main {
    flex: 1;
    min-width: 0;
}

.chat-thread {
    width: 340px;
    flex-shrink: 0;
}

